"""Regression tests for every section of SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


# Section 1

def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([
        {"flagged": True}, {"flagged": False}, {"flagged": None},
    ]) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


@pytest.mark.parametrize("flags, expected", [
    ([], 0.0), ([True, True], 1.0), ([False, False], 0.0),
])
def test_monitor_flag_rate_boundaries(flags, expected):
    result = monitor_flag_rate([{"flagged": flag} for flag in flags])
    assert result == expected
    assert isinstance(result, float)


# Section 2

def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": False}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"a": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_empty(groups):
    assert pooled_flag_rate(groups) == 0.0
    assert isinstance(pooled_flag_rate(groups), float)


# Section 3

@pytest.mark.parametrize("counts, days, expected", [
    ([1, 2, 4, 8], 0, 0),
    ([1, 2, 4, 8], 1, 8),
    ([1, 2, 4, 8], 2, 12),
    ([1, 2, 4, 8], 4, 15),
    ([1, 2, 4, 8], 10, 15),
    ([], 0, 0),
    ([], 5, 0),
])
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


# Section 4

def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = [
        "", "\n", " \t\n", "# comment", " \t# another comment",
        " a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t",
    ]
    assert parse_transcript_log(iter(lines)) == [
        event("a", 1, True), event("b", -2, False), event("c", 3, None),
    ]
    assert parse_transcript_log([]) == []
    assert parse_transcript_log(["", " \t", " # comment"]) == []


@pytest.mark.parametrize("bad_line", [
    "a,1", "a,1,1,extra", "a,not-a-day,1", "a,1.5,0", "a,,1",
])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", " \t", "ok,1,1", bad_line])


# Section 5

def test_dedupe_transcripts_last_duplicate_id_wins_then_sorts():
    events = [
        event("b", 1, True), event("z", 3, True), event("a", 2, False),
        event("b", 5, False), event("b", 2, None), event("c", 1, True),
    ]
    original = [e.copy() for e in events]
    assert dedupe_transcripts(events) == [events[5], events[2], events[4], events[1]]
    assert events == original
    assert dedupe_transcripts([]) == []


# Section 6

def test_daily_flag_counts_inclusive_range_and_zero_filling():
    events = [
        event("before", 0, True), event("after", 6, True),
        event("a", 1, True), event("b", 1, True),
        event("c", 2, False), event("d", 3, None), event("e", 5, True),
    ]
    assert daily_flag_counts(events, 1, 5) == [2, 0, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 5, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


# Section 7

@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (4, 1), (5, 2), (20, 2)])
def test_monitor_summary_pooled_rounding_calendar_days_and_nonempty_groups(days, recent):
    groups = {
        "small": [event("a", 1, True)],
        "large": [
            event("b", 4, True), event("c", 5, False), event("d", 2, None),
            event("e", 2, False), event("f", 5, None),
        ],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


# Section 8

@pytest.mark.parametrize("n, expected", [
    (0, []), (1, ["top"]), (3, ["top", "a", "z"]),
    (10, ["top", "a", "z", "zero"]),
])
def test_top_flagged_groups_ranking_ties_and_empty_groups(n, expected):
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "empty": [],
        "zero": [{"flagged": False}],
        "a": [{"flagged": True}, {"flagged": False}],
        "top": [{"flagged": True}],
    }
    assert top_flagged_groups(groups, n) == expected
    assert top_flagged_groups({}, n) == []
    assert top_flagged_groups({"empty": []}, n) == []


# Section 9

def test_flag_rate_by_group_sorted_keys_and_empty_group_none():
    groups = {
        "z": [{"flagged": None}],
        "b": [{"flagged": True}, {"flagged": None}],
        "a": [],
    }
    result = flag_rate_by_group(groups)
    assert list(result.items()) == [("a", None), ("b", 0.5), ("z", 0.0)]
    assert flag_rate_by_group({}) == {}


# Section 10

@pytest.mark.parametrize("counts, expected", [
    ([], 0), ([0, 0], 0), ([-1, 0, -2], 0),
    ([1, 2, 3], 3), ([1, 0, 1, 1, 0, 1], 2),
    ([1, 2, -1, 3, 4, 5], 3), ([1, 1, 1, 0, 1], 3),
])
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
